1288	        private RemoteLogMetadataStats calculateMetadataAndSize(Iterator<RemoteLogSegmentMetadata> segmentMetadataIter) {
1289	            // Good to have an API from RLMM to get the RemoteLogMetadataStats instead of going through all the segments
1290	            // and building it here.
1291	            Set<Integer> epochsSet = new HashSet<>();
1292	            int metadataCount = 0;
1293	            long sizeInBytes = 0;
1294	            long copyFinishedSegmentsSizeInBytes = 0;
1295	            while (segmentMetadataIter.hasNext()) {
1296	                RemoteLogSegmentMetadata segmentMetadata = segmentMetadataIter.next();
1297	                epochsSet.addAll(segmentMetadata.segmentLeaderEpochs().keySet());
1298	                metadataCount++;
1299	                RemoteLogSegmentState state = segmentMetadata.state();
1300	                // COPY_SEGMENT_STARTED state is excluded from the `sizeInBytes` calculation as it can pollute the
1301	                // metric during the upload retries.
1302	                if (state == RemoteLogSegmentState.COPY_SEGMENT_FINISHED) {
1303	                    copyFinishedSegmentsSizeInBytes += segmentMetadata.segmentSizeInBytes();
1304	                    sizeInBytes += segmentMetadata.segmentSizeInBytes();
1305	                } else if (state == RemoteLogSegmentState.DELETE_SEGMENT_STARTED) {
1306	                    sizeInBytes += segmentMetadata.segmentSizeInBytes();
1307	                }
1308	            }
1309	            return new RemoteLogMetadataStats(epochsSet, metadataCount, sizeInBytes, copyFinishedSegmentsSizeInBytes);
1310	        }
